97	const SIDEBAR_WIDTH_KEY = "bb.sidebar.width";
98	const SIDEBAR_OPEN_KEY = "bb.sidebar.open";
99	const SIDEBAR_MIN_WIDTH = 240;
100	const SIDEBAR_MAX_WIDTH = 460;
101	const SIDEBAR_DEFAULT_WIDTH = 320;
102	
103	function clampSidebarWidth(value: number) {
104	  return Math.min(SIDEBAR_MAX_WIDTH, Math.max(SIDEBAR_MIN_WIDTH, value));
105	}
106	
107	const sidebarWidthStorage = createLocalStorageSyncStorage<number>({
108	  parse: (storedValue, initialValue) => {
109	    if (storedValue === null) {
110	      return initialValue;
111	    }
112	    const parsedValue = Number(storedValue);
113	    if (!Number.isFinite(parsedValue)) {
114	      return initialValue;
115	    }
116	    return clampSidebarWidth(parsedValue);
117	  },
118	  serialize: (value) => String(clampSidebarWidth(value)),
119	});
120	const sidebarWidthAtom = atomWithStorage<number>(
121	  SIDEBAR_WIDTH_KEY,
122	  SIDEBAR_DEFAULT_WIDTH,
123	  sidebarWidthStorage,
124	  { getOnInit: true },
125	);
126	
127	// Held in jotai (rather than as `useState` inside AppLayout) so that toggling
128	// the sidebar does not re-render AppLayout — only the small bridge below
129	// subscribes. AppLayout's `children` reference stays stable across toggles,
130	// so React's element-reference bailout skips re-rendering the entire route
131	// subtree (ThreadDetailView, the timeline, etc.).
132	const sidebarOpenStorage = createLocalStorageSyncStorage<boolean>({
133	  parse: (storedValue, initialValue) => {
134	    if (storedValue === "true") return true;
135	    if (storedValue === "false") return false;
136	    return initialValue;
137	  },
138	  serialize: (value) => String(value),
139	});
140	const sidebarOpenAtom = atomWithStorage<boolean>(
141	  SIDEBAR_OPEN_KEY,
142	  true,
143	  sidebarOpenStorage,
144	  { getOnInit: true },
145	);
