147	interface SidebarStateBridgeProps {
148	  className?: string;
149	  providerRef: Ref<HTMLDivElement>;
150	  style: CSSProperties;
151	  children: ReactNode;
152	}
153	
154	type SidebarResizeMouseEvent = ReactMouseEvent<HTMLDivElement>;
155	type SidebarOpenChangeHandler = (open: boolean) => void;
156	
157	type SidebarProviderStyle = CSSProperties & {
158	  "--sidebar-width": string;
159	};
