161	function SidebarStateBridge({
162	  className,
163	  providerRef,
164	  style,
165	  children,
166	}: SidebarStateBridgeProps) {
167	  const [open, setOpen] = useAtom(sidebarOpenAtom);
168	  const handleOpenChange = useCallback<SidebarOpenChangeHandler>(
169	    (nextOpen) => {
170	      setOpen(nextOpen);
171	      window.requestAnimationFrame(dispatchBrowserViewBoundsSync);
172	    },
173	    [setOpen],
174	  );
175	  useAppCommandHandler("sidebar.toggle", () => {
176	    handleOpenChange(!open);
177	    return true;
178	  });
179	  return (
180	    <SidebarProvider
181	      ref={providerRef}
182	      style={style}
183	      className={className}
184	      data-testid="app-layout-root"
185	      open={open}
186	      onOpenChange={handleOpenChange}
187	    >
188	      {children}
189	    </SidebarProvider>
190	  );
191	}
