204	/**
205	 * Sidebar toggle pinned at the app's top-left, rendered once at the layout root
206	 * — outside the sliding sidebar panel and the content inset — so it holds a
207	 * constant position while the sidebar animates in/out behind it, instead of
208	 * riding whichever container would otherwise host it. The collapsed page header
209	 * reserves its footprint as animated padding (see AppPageHeader), so toggling
210	 * slides the header content smoothly past it rather than snapping around a
211	 * toggle that mounts/unmounts in the header.
212	 *
213	 * Desktop chrome keeps the strip a window-drag region; only the button itself
214	 * is no-drag, so the title strip above and below the (shorter) button stays
215	 * draggable rather than becoming an oversized dead zone. When macOS traffic
216	 * lights are visible it offsets past them; in fullscreen, where the lights are
217	 * hidden, it uses the same small top-left inset as browser chrome.
218	 */
219	function SidebarTriggerOverlay({
220	  reserveMacosTrafficLights,
221	  usesDesktopChrome,
222	}: SidebarTriggerOverlayProps) {
223	  const shortcut = useAppCommandShortcut("sidebar.toggle");
224	  const triggerProps = {
225	    "aria-label": shortcut
226	      ? `Toggle sidebar (${shortcut.label})`
227	      : "Toggle sidebar",
228	    "aria-keyshortcuts": shortcut?.ariaKeyshortcuts,
229	  };
230	  if (usesDesktopChrome) {
231	    return (
232	      <div
233	        data-testid="app-desktop-sidebar-trigger"
234	        className={cn(
235	          "fixed top-0 z-50",
236	          CHROME_ROW_CLASS,
237	          reserveMacosTrafficLights
238	            ? MACOS_TRAFFIC_LIGHT_RESERVE_OFFSET_CLASS
239	            : "left-0",
240	          !reserveMacosTrafficLights && BROWSER_SIDEBAR_TRIGGER_INSET_CLASS,
241	          MACOS_WINDOW_DRAG_CLASS,
242	        )}
243	      >
244	        {/* The overlay's CHROME_ROW_CLASS box-centers the trigger on the shared
245	            traffic-light axis, matching the sidebar arrows and page-title
246	            header in desktop chrome. */}
247	        <SidebarTrigger
248	          className={MACOS_CHROME_CONTROL_NO_DRAG_CLASS}
249	          {...triggerProps}
250	        />
251	        <AppCommandShortcutHint
252	          shortcut={shortcut}
253	          className={cn(
254	            "absolute left-full ml-1",
255	            MACOS_CHROME_TRAFFIC_LIGHT_AXIS_NUDGE_CLASS,
256	          )}
257	        />
258	      </div>
259	    );
260	  }
261	  return (
262	    <div
263	      data-testid="app-sidebar-trigger-overlay"
264	      className={cn(
265	        "fixed top-[env(safe-area-inset-top)] left-[env(safe-area-inset-left)] z-50",
266	        CHROME_ROW_CLASS,
267	        BROWSER_SIDEBAR_TRIGGER_INSET_CLASS,
268	      )}
269	    >
270	      <SidebarTrigger {...triggerProps} />
271	      <AppCommandShortcutHint
272	        shortcut={shortcut}
273	        className="absolute left-full ml-1"
274	      />
275	    </div>
276	  );
277	}
