286	function resolveRouteTitle(
287	  pathname: string,
288	): { title: string; subtitle?: string } | undefined {
289	  // The global settings page owns /settings/:section. Legacy plugin settings
290	  // links still match briefly before AppRoutes redirects them to Tools.
291	  if (matchPath(`${SETTINGS_ROUTE_PATH}/*`, pathname)) {
292	    return routeTitles[SETTINGS_ROUTE_PATH];
293	  }
294	  return routeTitles[pathname];
295	}
