297	interface AppHeaderProps {
298	  /**
299	   * True for routes that should use quiet chrome. This suppresses the center
300	   * title; project-scoped quiet routes also get project actions on the right.
301	   */
302	  usesProjectChromeStyle: boolean;
303	  usesDesktopChrome: boolean;
304	  isSettingsView: boolean;
305	  projectId?: string;
306	  project?: ProjectResponse;
307	  /** Registered navPanel when this is a plugin panel route (design §5.2):
308	   * the shared header shows plugin icon + title, plus the registration's
309	   * `headerContent` as the actions. */
310	  pluginPanel?: PluginNavPanelSlot;
311	  /** The panel route's splat remainder ("" at the panel root). */
312	  pluginPanelSubPath?: string;
313	  meta: {
314	    title: string;
315	    subtitle?: string;
316	    breadcrumbs?: Array<{ label: string; to?: string }>;
317	  };
318	}
