320	function AppHeader({
321	  usesProjectChromeStyle,
322	  usesDesktopChrome,
323	  isSettingsView,
324	  projectId,
325	  project,
326	  pluginPanel,
327	  pluginPanelSubPath,
328	  meta,
329	}: AppHeaderProps) {
330	  const headerBreadcrumbs = meta.breadcrumbs;
331	  const headerTitle =
332	    headerBreadcrumbs || usesProjectChromeStyle ? undefined : meta.title;
333	
334	  const hasCenterContent =
335	    Boolean(headerBreadcrumbs) ||
336	    Boolean(headerTitle) ||
337	    Boolean(meta.subtitle);
338	
339	  const center = headerBreadcrumbs ? (
340	    <div className="min-w-0 flex-1">
341	      <AppBreadcrumbs
342	        breadcrumbs={headerBreadcrumbs}
343	        usesDesktopChrome={usesDesktopChrome}
344	      />
345	    </div>
346	  ) : pluginPanel ? (
347	    <PluginPanelHeaderCenter panel={pluginPanel} />
348	  ) : hasCenterContent ? (
349	    <div className="min-w-0 flex-1">
350	      {headerTitle ? (
351	        <p className="truncate text-sm font-semibold">{headerTitle}</p>
352	      ) : null}
353	      {meta.subtitle ? (
354	        <p className="truncate text-xs text-muted-foreground">
355	          {meta.subtitle}
356	        </p>
357	      ) : null}
358	    </div>
359	  ) : null;
360	
361	  const actions = pluginPanel ? (
362	    <PluginPanelHeaderActions
363	      panel={pluginPanel}
364	      subPath={pluginPanelSubPath ?? ""}
365	    />
366	  ) : usesProjectChromeStyle &&
367	    projectId &&
368	    !isProjectlessProjectId(projectId) ? (
369	    <>
370	      <Link
371	        to={getProjectSettingsRoutePath(projectId)}
372	        className={cn(
373	          HEADER_ICON_BUTTON_CLASS,
374	          "inline-flex items-center justify-center transition-colors",
375	          isSettingsView
376	            ? "bg-state-active text-foreground"
377	            : "text-muted-foreground hover:bg-state-hover hover:text-foreground",
378	        )}
379	        aria-label="Project settings"
380	        aria-current={isSettingsView ? "page" : undefined}
381	      >
382	        <Icon name="Settings" />
383	      </Link>
384	      {project ? (
385	        <ProjectActionsMenu
386	          project={project}
387	          triggerClassName={HEADER_ICON_BUTTON_CLASS}
388	        />
389	      ) : null}
390	    </>
391	  ) : null;
392	
393	  return <AppPageHeader center={center} actions={actions} />;
394	}
