400	export function AppLayout({ children }: AppLayoutProps) {
401	  const quickCreateProject = useQuickCreateProjectController();
402	  const isCompactViewport = useIsCompactViewport();
403	  const threadSplitsEnabled = useThreadSplitsEnabled();
404	  const splitWorkspaceActive = useSplitWorkspaceActive();
405	  const store = useStore();
406	  const contentShellRef = useRef<HTMLDivElement>(null);
407	  useMobileVisualViewportHeight(contentShellRef, isCompactViewport);
408	  const location = useLocation();
409	  const [resourceRouteLabel, setResourceRouteLabel] = useAtom(
410	    resourceRouteLabelAtom,
411	  );
412	  useEffect(() => {
413	    setResourceRouteLabel(null);
414	    function handleResourceRouteLabel(event: Event) {
415	      if (!(event instanceof CustomEvent)) return;
416	      const detail = event.detail;
417	      if (
418	        typeof detail !== "object" ||
419	        detail === null ||
420	        !("label" in detail) ||
421	        (typeof detail.label !== "string" && detail.label !== null)
422	      ) {
423	        return;
424	      }
425	      setResourceRouteLabel(detail.label);
426	    }
427	    window.addEventListener(
428	      RESOURCE_ROUTE_LABEL_EVENT,
429	      handleResourceRouteLabel,
430	    );
431	    return () => {
432	      window.removeEventListener(
433	        RESOURCE_ROUTE_LABEL_EVENT,
434	        handleResourceRouteLabel,
435	      );
436	    };
437	  }, [location.pathname, setResourceRouteLabel]);
438	  const navigate = useNavigate();
439	  const {
440	    appRoutePath,
441	    settingsRoutePath,
442	    toolsBackRoutePath,
443	    toolsRoutePath,
444	  } = useAppSettingsRouteMemory();
445	  useEffect(
446	    () =>
447	      wsManager.onThreadOpen((signal) => {
448	        const route = getThreadRoutePath({
449	          projectId: signal.projectId,
450	          threadId: signal.threadId,
451	        });
452	        if (!threadSplitsEnabled) {
453	          void navigate(route);
454	          return;
455	        }
456	        const current = store.get(splitLayoutAtom);
457	        const alreadyOpen =
458	          current !== null &&
459	          findPaneByThread(current.root, signal.projectId, signal.threadId) !==
460	            null;
461	        const next = applyThreadOpenToLayout(
462	          current,
463	          { projectId: signal.projectId, threadId: signal.threadId },
464	          isCompactViewport ? "replace" : signal.split,
465	        );
466	        if (next !== current) {
467	          store.set(splitLayoutAtom, next);
468	        }
469	        void navigate(route, alreadyOpen ? { replace: true } : undefined);
470	      }),
471	    [isCompactViewport, navigate, store, threadSplitsEnabled],
472	  );
473	  useAppCommandHandler("thread.new", () => {
474	    void navigate(getRootComposeRoutePath(), {
475	      state: { focusPrompt: true },
476	    });
477	    return true;
478	  });
479	  useAppCommandHandler("settings.open", () => {
480	    void navigate(settingsRoutePath);
481	    return true;
482	  });
483	  // Native server rail "+" tile.
484	  useAppCommandHandler("settings.openServers", () => {
485	    void navigate(`${SETTINGS_ROUTE_PATH}/servers`);
486	    return true;
487	  });
488	  const {
489	    projectId,
490	    threadId,
491	    isThreadView,
492	    isArchivedView,
493	    isSettingsView,
494	    isRootView,
495	  } = useRouteState();
496	  const archivedSectionId = isArchivedView
497	    ? new URLSearchParams(location.search).get("sectionId")
498	    : null;
499	  // Plugin panel routes ride the shared header (design §5.2): icon + panel
500	  // title in the center, the registration's headerContent as the actions.
501	  const { navPanels } = usePluginSlots();
502	  // Global settings routes swap the app sidebar for the settings sidebar.
503	  const isGlobalSettingsView =
504	    matchPath(`${SETTINGS_ROUTE_PATH}/*`, location.pathname) !== null;
505	  const systemConfigQuery = useSystemConfig();
506	  const toolsHubEnabled = systemConfigQuery.data?.experiments.toolsHub === true;
507	  const isGlobalToolsView =
508	    toolsHubEnabled && isToolsRoutePath(location.pathname);
509	  const pluginPanelMatch = matchPath(
510	    PLUGIN_PANEL_ROUTE_PATH,
511	    location.pathname,
512	  );
513	  const pluginPanel = pluginPanelMatch
514	    ? navPanels.find(
515	        (candidate) =>
516	          candidate.pluginId === pluginPanelMatch.params.pluginId &&
517	          candidate.path === pluginPanelMatch.params.panelPath,
518	      )
519	    : undefined;
520	  const sidebarNavigationQuery = useSidebarNavigation();
521	  const projects = useMemo(
522	    () => sidebarNavigationQuery.data?.projects.map(stripProjectThreads),
523	    [sidebarNavigationQuery.data],
524	  );
525	  const sidebarThreads = useMemo(() => {
526	    const sidebarNavigation = sidebarNavigationQuery.data;
527	    if (!sidebarNavigation) {
528	      return [];
529	    }
530	    return [
531	      ...sidebarNavigation.projects.flatMap((project) => project.threads),
532	      ...sidebarNavigation.personalProject.threads,
533	    ];
534	  }, [sidebarNavigationQuery.data]);
535	  const titleMentionResources = useMemo(() => {
536	    const sectionNamesById = new Map<string, string>();
537	    const projectNamesById = new Map<string, string>();
538	    const threadById = new Map(
539	      sidebarThreads.map((entry) => [entry.id, entry]),
540	    );
541	    const navigation = sidebarNavigationQuery.data;
542	    if (navigation) {
543	      for (const section of navigation.sections) {
544	        sectionNamesById.set(section.id, section.name);
545	      }
546	      for (const projectEntry of navigation.projects) {
547	        projectNamesById.set(projectEntry.id, projectEntry.name);
548	      }
549	      projectNamesById.set(
550	        navigation.personalProject.id,
551	        navigation.personalProject.name,
552	      );
553	    }
554	    return { sectionNamesById, projectNamesById, threadById };
555	  }, [sidebarNavigationQuery.data, sidebarThreads]);
556	  const threadDetailBootstrapQuery = useThreadDetailBootstrap(threadId ?? "", {
557	    enabled: isThreadView && Boolean(threadId),
558	    timelinePrefetch: isThreadView && Boolean(threadId),
559	  });
560	  const hasThreadDetailBootstrapSettled =
561	    threadDetailBootstrapQuery.isSuccess || threadDetailBootstrapQuery.isError;
562	  const [sidebarWidth, setSidebarWidth] = useAtom(sidebarWidthAtom);
563	  const [isSidebarResizing, setIsSidebarResizing] = useState(false);
564	  const providerRef = useRef<HTMLDivElement>(null);
565	  const startXRef = useRef(0);
566	  const startWidthRef = useRef(0);
567	  const liveWidthRef = useRef(sidebarWidth);
568	  const animationFrameRef = useRef<number | null>(null);
569	  // Plugin panel routes hand their header to the split workspace, which draws a
570	  // pane header per pane. When the workspace is inactive it draws none, so the
571	  // shared header must come back — it reserves the sidebar trigger footprint,
572	  // and without it the trigger overlays the panel body.
573	  const showHeader =
574	    !isThreadView &&
575	    !isRootView &&
576	    !(splitWorkspaceActive && pluginPanelMatch !== null);
577	  const [desktopInfo] = useState(getBbDesktopInfo);
578	  const desktopWindowState = useDesktopWindowState();
579	  const usesDesktopChrome = shouldUseMacosDesktopChrome(desktopInfo);
580	  const reserveMacosTrafficLights = shouldReserveMacosTrafficLights({
581	    desktopInfo,
582	    windowState: desktopWindowState,
583	  });
584	  const sidebarProviderStyle: SidebarProviderStyle = {
585	    "--sidebar-width": `${sidebarWidth}px`,
586	  };
587	
588	  const project = projectId
589	    ? projects?.find((candidate) => candidate.id === projectId)
590	    : undefined;
591	  const archivedSectionName = archivedSectionId
592	    ? (sidebarNavigationQuery.data?.sections.find(
593	        (section) => section.id === archivedSectionId,
594	      )?.name ?? archivedSectionId)
595	    : null;
596	  const projectName = projectId ? project?.name : undefined;
597	  const projectLabel = projectName ?? (projectId ? projectId : undefined);
598	  const { data: thread } = useThread(threadId ?? "", {
599	    enabled:
600	      Boolean(threadId) && (!isThreadView || hasThreadDetailBootstrapSettled),
601	    refetchOnMount:
602	      isThreadView &&
603	      didThreadDetailBootstrapRefreshAfterMount(threadDetailBootstrapQuery)
604	        ? false
605	        : "always",
606	  });
607	  const threadDisplayTitle = thread
608	    ? getThreadDisplayTitle(thread)
609	    : threadId
610	      ? `Thread ${threadId.slice(0, 8)}`
611	      : "Thread";
612	  // Gated with the rest of the Tools surface: ROOT_ROUTE_ALIASES maps /skills
613	  // into Tools crumbs, so a gate-off user following an old link would otherwise
614	  // see Tools chrome for the whole config fetch before ToolsExperimentGate
615	  // redirects them away.
616	  const toolsBreadcrumbs = toolsHubEnabled
617	    ? resolveToolsBreadcrumbs(
618	        location.pathname,
619	        location.search,
620	        resourceRouteLabel,
621	      )
622	    : null;
623	  const automationBreadcrumbs = resolveAutomationBreadcrumbs(
624	    location.pathname,
625	    resourceRouteLabel,
626	  );
627	  const routeBreadcrumbs = toolsBreadcrumbs ?? automationBreadcrumbs;
628	  const meta = isThreadView
629	    ? {
630	        title: thread ? getThreadDisplayTitle(thread) : "Thread",
631	        subtitle: undefined,
632	      }
633	    : routeBreadcrumbs
634	      ? {
635	          title: "",
636	          subtitle: undefined,
637	          breadcrumbs: routeBreadcrumbs,
638	        }
639	      : isArchivedView && projectId
640	        ? isProjectlessProjectId(projectId)
641	          ? {
642	              title: "",
643	              subtitle: undefined,
644	              breadcrumbs: [
645	                { label: "Threads", to: getRootComposeRoutePath() },
646	                ...(archivedSectionName
647	                  ? [{ label: archivedSectionName }]
648	                  : []),
649	                { label: "Archived" },
650	              ],
651	            }
652	          : {
653	              title: "",
654	              subtitle: undefined,
655	              breadcrumbs: [
656	                {
657	                  label: projectLabel ?? projectId,
658	                  to: getLegacyProjectComposeRoutePath(projectId),
659	                },
660	                { label: "Archived" },
661	              ],
662	            }
663	        : isSettingsView && projectId
664	          ? {
665	              title: "",
666	              subtitle: undefined,
667	              breadcrumbs: [
668	                {
669	                  label: projectLabel ?? projectId,
670	                  to: getLegacyProjectComposeRoutePath(projectId),
671	                },
672	                { label: "Settings" },
673	              ],
674	            }
675	          : projectId
676	            ? {
677	                title: projectLabel ?? projectId,
678	                subtitle: undefined,
679	              }
680	            : (resolveRouteTitle(location.pathname) ?? { title: "" });
681	
682	  const documentTitle = (() => {
683	    if (isThreadView) {
684	      return threadDisplayTitle;
685	    }
686	    if (pluginPanel) {
687	      return pluginPanel.title;
688	    }
689	    if (routeBreadcrumbs) {
690	      const sectionLabel = routeBreadcrumbs[0]?.label ?? "BB";
691	      const pageLabel = routeBreadcrumbs.at(-1)?.label ?? sectionLabel;
692	      return pageLabel === sectionLabel
693	        ? sectionLabel
694	        : `${pageLabel} · ${sectionLabel}`;
695	    }
696	    if (isArchivedView && projectId) {
