699	          ? `${archivedSectionName} · Archived`
700	          : "Threads · Archived";
701	      }
702	      return `${projectLabel ?? projectId} · Archived`;
703	    }
704	    if (isSettingsView && projectId) {
705	      return `${projectLabel ?? projectId} · Settings`;
706	    }
707	    if (projectId) {
708	      return projectLabel ?? projectId;
709	    }
710	    const routeTitle = resolveRouteTitle(location.pathname)?.title;
711	    return routeTitle && routeTitle.length > 0 ? routeTitle : "BB";
712	  })();
713	  // The sidebar list omits archived threads and side chats, so it can't answer
714	  // whether the currently-viewed thread is blocked on input. Read the current
715	  // thread's pending interactions directly (the thread view already warms this
716	  // cache) so an in-view thread waiting on the user always lights the favicon,
717	  // mirroring how the in-view unread signal covers every thread kind.
718	  const currentThreadPendingInteractionsQuery = useThreadPendingInteractions(
719	    threadId ?? "",
720	    { enabled: isThreadView && Boolean(threadId) },
721	  );
722	  const currentThreadHasPendingInteraction =
723	    getLatestPendingInteraction(currentThreadPendingInteractionsQuery.data) !==
724	    null;
725	  const faviconBadge = shouldShowFaviconAttentionDot({
726	    currentThreadHasPendingInteraction,
727	    isThreadView,
728	    sidebarThreads,
729	    thread,
730	  })
731	    ? "unread"
732	    : "none";
733	  useFaviconBadge(faviconBadge);
734	
735	  const handleResizeMouseDown = useCallback(
736	    (event: SidebarResizeMouseEvent) => {
737	      event.preventDefault();
738	      setIsSidebarResizing(true);
739	      startXRef.current = event.clientX;
740	      startWidthRef.current = liveWidthRef.current;
741	      document.body.classList.add("sidebar-resizing");
742	      applyResizeCursor("horizontal");
743	      document.body.style.userSelect = "none";
744	    },
745	    [],
746	  );
747	
748	  const finishSidebarResize = useCallback(() => {
749	    if (animationFrameRef.current !== null) {
750	      window.cancelAnimationFrame(animationFrameRef.current);
751	      animationFrameRef.current = null;
752	    }
753	    providerRef.current?.style.setProperty(
754	      "--sidebar-width",
755	      `${liveWidthRef.current}px`,
756	    );
757	    dispatchBrowserViewBoundsSync();
758	    setSidebarWidth(liveWidthRef.current);
759	    setIsSidebarResizing(false);
760	    resetSidebarResizeDocumentState();
761	  }, [setSidebarWidth]);
762	
763	  useEffect(() => {
764	    if (!isSidebarResizing) return;
765	
766	    const applyLiveWidth = () => {
767	      animationFrameRef.current = null;
768	      providerRef.current?.style.setProperty(
769	        "--sidebar-width",
770	        `${liveWidthRef.current}px`,
771	      );
772	      dispatchBrowserViewBoundsSync();
773	    };
774	
775	    const handleMouseMove = (event: MouseEvent) => {
776	      const delta = event.clientX - startXRef.current;
777	      liveWidthRef.current = clampSidebarWidth(startWidthRef.current + delta);
778	      if (animationFrameRef.current === null) {
