780	          window.requestAnimationFrame(applyLiveWidth);
781	      }
782	    };
783	
784	    const handleKeyDown = (event: KeyboardEvent) => {
785	      if (event.key === "Escape") {
786	        finishSidebarResize();
787	      }
788	    };
789	
790	    window.addEventListener("mousemove", handleMouseMove);
791	    window.addEventListener("mouseup", finishSidebarResize);
792	    window.addEventListener("blur", finishSidebarResize);
793	    window.addEventListener("keydown", handleKeyDown);
794	    return () => {
795	      window.removeEventListener("mousemove", handleMouseMove);
796	      window.removeEventListener("mouseup", finishSidebarResize);
797	      window.removeEventListener("blur", finishSidebarResize);
798	      window.removeEventListener("keydown", handleKeyDown);
799	      if (animationFrameRef.current !== null) {
800	        window.cancelAnimationFrame(animationFrameRef.current);
801	        animationFrameRef.current = null;
802	      }
803	      resetSidebarResizeDocumentState();
804	    };
805	  }, [finishSidebarResize, isSidebarResizing]);
806	
807	  useEffect(() => {
808	    liveWidthRef.current = sidebarWidth;
809	  }, [sidebarWidth]);
810	
811	  useEffect(() => {
812	    if (typeof document === "undefined") return;
813	    document.title = documentTitle;
814	  }, [documentTitle]);
815	
816	  return (
817	    <ToolsHubExperimentProvider enabled={toolsHubEnabled}>
818	      <ProjectActionsProvider>
819	        <ThreadTitleMentionResourcesProvider {...titleMentionResources}>
820	          <ThreadActionsProvider>
821	            <IframeDragGuardOverlay active={isSidebarResizing} />
822	            <SidebarStateBridge
823	              providerRef={providerRef}
824	              style={sidebarProviderStyle}
825	            >
826	              {isGlobalSettingsView ? (
827	                <SettingsSidebar
828	                  onResizeMouseDown={handleResizeMouseDown}
829	                  isResizing={isSidebarResizing}
830	                  showTopReserve={true}
831	                  appRoutePath={appRoutePath}
832	                />
833	              ) : isGlobalToolsView ? (
834	                <ToolsSidebar
835	                  onResizeMouseDown={handleResizeMouseDown}
836	                  isResizing={isSidebarResizing}
837	                  showTopReserve={true}
838	                  appRoutePath={toolsBackRoutePath}
839	                />
840	              ) : (
841	                <AppSidebar
842	                  onResizeMouseDown={handleResizeMouseDown}
843	                  isResizing={isSidebarResizing}
844	                  showTopReserve={true}
845	                  settingsRoutePath={settingsRoutePath}
846	                  toolsRoutePath={toolsHubEnabled ? toolsRoutePath : undefined}
847	                />
848	              )}
849	              <SidebarInset>
850	                <div
851	                  ref={contentShellRef}
852	                  data-testid="app-layout-content-shell"
853	                  className="relative flex h-full min-h-0 min-w-0 w-full flex-col pt-[env(safe-area-inset-top)] pr-[env(safe-area-inset-right)] pb-[env(safe-area-inset-bottom)] pl-[env(safe-area-inset-left)]"
854	                >
855	                  {showHeader ? (
856	                    <AppHeader
857	                      usesDesktopChrome={usesDesktopChrome}
858	                      usesProjectChromeStyle={
859	                        isRootView || isArchivedView || isSettingsView
860	                      }
861	                      isSettingsView={isSettingsView}
862	                      projectId={projectId}
863	                      project={project}
864	                      pluginPanel={pluginPanel}
865	                      pluginPanelSubPath={pluginPanelMatch?.params["*"] ?? ""}
866	                      meta={meta}
867	                    />
